const listRuns = `-- name: ListRuns :many
SELECT id, phase, outcome, repository_id, catalog_revision_id, commit_sha, target_name, action_name, parameters, placement_name, cluster_name, source, idempotency_key, request_digest, snapshot, created_at, assigned_at, preparing_at, started_at, finished_at, last_observed_at, cancellation_requested_at, job_uid, outcome_reason, outcome_message, exit_code, created_by_principal_id, created_by_snapshot, canceled_by_principal_id, canceled_by_snapshot, rerun_of_run_id, rerun_mode, target_id, target_relevance_commit_sha, review_state, review_decided_by_principal_id, review_decided_by_snapshot, review_decided_at, review_comment
FROM runs
WHERE (
    $1::uuid IS NULL
    OR repository_id = $1
)
AND (
    $2::text IS NULL
    OR commit_sha = $2
)
AND (
    $3::uuid IS NULL
    OR EXISTS (
        SELECT 1
        FROM run_artifact_inputs
        WHERE run_artifact_inputs.run_id = runs.id
          AND run_artifact_inputs.artifact_id = $3
    )
)
AND (
    $4::uuid IS NULL
    OR target_id = $4
)
AND (
    $5::text IS NULL
    OR cluster_name = $5
)
AND (
    $6::text IS NULL
    OR phase = $6
)
AND (
    $7::text IS NULL
    OR review_state = $7
)
ORDER BY created_at DESC, id DESC
LIMIT $9
OFFSET $8
`

type ListRunsParams struct {
	RepositoryID    pgtype.UUID
	CommitSha       *string
	InputArtifactID pgtype.UUID
	TargetID        pgtype.UUID
	ClusterName     *string
	Phase           *string
	ReviewState     *string
	ResultOffset    int32
	ResultLimit     int32
}

func (q *Queries) ListRuns(ctx context.Context, arg ListRunsParams) ([]Run, error) {
	rows, err := q.db.Query(ctx, listRuns,
		arg.RepositoryID,
		arg.CommitSha,
		arg.InputArtifactID,
		arg.TargetID,
		arg.ClusterName,
		arg.Phase,
		arg.ReviewState,
		arg.ResultOffset,
		arg.ResultLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Run
	for rows.Next() {
		var i Run
		if err := rows.Scan(
			&i.ID,
			&i.Phase,
			&i.Outcome,
			&i.RepositoryID,
			&i.CatalogRevisionID,
			&i.CommitSha,
			&i.TargetName,
			&i.ActionName,
			&i.Parameters,
			&i.PlacementName,
			&i.ClusterName,
			&i.Source,
			&i.IdempotencyKey,
			&i.RequestDigest,
			&i.Snapshot,
			&i.CreatedAt,
			&i.AssignedAt,
			&i.PreparingAt,
			&i.StartedAt,
			&i.FinishedAt,
			&i.LastObservedAt,
			&i.CancellationRequestedAt,
			&i.JobUid,
			&i.OutcomeReason,
			&i.OutcomeMessage,
			&i.ExitCode,
			&i.CreatedByPrincipalID,
			&i.CreatedBySnapshot,
			&i.CanceledByPrincipalID,
			&i.CanceledBySnapshot,
			&i.RerunOfRunID,
			&i.RerunMode,
			&i.TargetID,
			&i.TargetRelevanceCommitSha,
			&i.ReviewState,
			&i.ReviewDecidedByPrincipalID,
			&i.ReviewDecidedBySnapshot,
			&i.ReviewDecidedAt,
			&i.ReviewComment,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

